<?php require_once '../config/database.php'; include '../layouts/header.php'; include '../layouts/navbar.php'; $r=$conn->query("SELECT * FROM alarm_history ORDER BY id DESC LIMIT 200"); ?><div class="container-fluid"><div class="row"><div class="col-lg-2 p-0"><?php include '../layouts/sidebar.php'; ?></div><main class="col-lg-10 p-4"><div class="card shadow-sm"><div class="card-header fw-bold">Alarm History</div><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>ID</th><th>Type</th><th>Value</th><th>Message</th><th>Status</th><th>Time</th></tr></thead><tbody><?php while($x=$r->fetch_assoc()): ?><tr><td><?= (int)$x['id'] ?></td><td><?= htmlspecialchars($x['alarm_type']) ?></td><td><?= htmlspecialchars($x['alarm_value']) ?></td><td><?= htmlspecialchars($x['message']) ?></td><td><?= htmlspecialchars($x['status']) ?></td><td><?= htmlspecialchars($x['created_at']) ?></td></tr><?php endwhile; ?></tbody></table></div></div></main></div></div><?php include '../layouts/footer.php'; ?>
